.custom-radio {
  position: relative;
  padding-left: 30px;
  cursor: pointer;
  display: inline-block;
  line-height: 20px;
  font-size: 16px; }

.custom-radio:before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 16px;
  /* Размер кольца */
  height: 16px;
  /* Размер кольца */
  border-radius: 50%;
  /* Круглая форма для кольца */
  border: 2px solid #ccc;
  /* Цвет границы для невыбранного состояния */
  background: white;
  /* Цвет фона кольца */ }

.custom-radio:after {
  content: '';
  position: absolute;
  left: 4px;
  /* Отступ для центрирования точки */
  top: 50%;
  transform: translateY(-50%);
  width: 8px;
  /* Размер точки */
  height: 8px;
  /* Размер точки */
  border-radius: 50%;
  /* Круглая форма для точки */
  background: transparent;
  /* Цвет точки по умолчанию (прозрачный) */ }

input[type='radio']:checked + .custom-radio:before {
  border-color: #343434;
  /* Цвет границы для отмеченного состояния */ }

input[type='radio']:checked + .custom-radio:after {
  background: #0560d8;
